    scrim.resize(SW, H);
    scrim.fills = [paint("ink", 0.32)];
    f.appendChild(scrim);
    const sh = box("VERTICAL", { name: "Folha · " + title, gap: 16, pad: [10, 20, 32, 20], fill: "surface", effects: SHADOWS.sheet });
    sh.topLeftRadius = sh.topRightRadius = 24;
